50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	};
61	
62	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
63	
64	const policyBasePremiumOf = (items: Item[]): number =>
65	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
66	
67	const quote = ({ items }: QuoteStep): QuoteResult => {
68	  const policyBase = policyBasePremiumOf(items);
69	
70	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
71	
72	  const premiumBeforeRounding =
73	    policyBase + firstInsuranceSurcharge + PROCESSING_FEE;
74	
75	  return { premium: Math.ceil(premiumBeforeRounding) };
76	};
77	
78	const runStep = (step: Step): StepResult => {
79	  if (step.op === "quote") return quote(step);
80	
81	  throw new Error(`unsupported step: ${step.op}`);
82	};
83	
84	export const runScenario = (scenario: Scenario): ScenarioResult => ({
85	  results: scenario.steps.map(runStep),
86	});
